                if (orderPaymentView.SettledFeeAmountOption.Value != null)
                    writer.WriteNumber("settledFeeAmount", orderPaymentView.SettledFeeAmountOption.Value!.Value);
                else
                    writer.WriteNull("settledFeeAmount");

            if (orderPaymentView.SettledNetAmountOption.IsSet)
                if (orderPaymentView.SettledNetAmountOption.Value != null)
                    writer.WriteNumber("settledNetAmount", orderPaymentView.SettledNetAmountOption.Value!.Value);
                else
                    writer.WriteNull("settledNetAmount");

            if (orderPaymentView.SettlementDateOption.IsSet)
                if (orderPaymentView.SettlementDateOption.Value != null)
                    writer.WriteString("settlementDate", orderPaymentView.SettlementDateOption.Value!.Value.ToString(SettlementDateFormat));
                else
                    writer.WriteNull("settlementDate");

            if (orderPaymentView.SettlementReportIdOption.IsSet)
                if (orderPaymentView.SettlementReportIdOption.Value != null)
                    writer.WriteString("settlementReportId", orderPaymentView.SettlementReportIdOption.Value!.Value);
                else
                    writer.WriteNull("settlementReportId");

            if (orderPaymentView.LastDiscrepancyKindOption.IsSet)
                if (orderPaymentView.LastDiscrepancyKindOption!.Value != null)
                {
                    var lastDiscrepancyKindRawValue = DiscrepancyKindValueConverter.ToJsonValue(orderPaymentView.LastDiscrepancyKindOption.Value!.Value);
                    writer.WriteString("lastDiscrepancyKind", lastDiscrepancyKindRawValue);
                }
                else
                    writer.WriteNull("lastDiscrepancyKind");
        }
    }
}
